-- CATALOGO-COMPLETO 18/11/2026 — 62 descrizioni e 2 schede Hōki, nessun nuovo potere.
-- Inattive, jutsu, XP, costi, requisiti, assegnazioni e codice applicativo invariati.
BEGIN;
SET LOCAL lock_timeout='4s';
LOCK TABLE public.clan_techniques IN SHARE ROW EXCLUSIVE MODE;
DO $catalog_patch$
DECLARE patch jsonb;current_row jsonb;expected_row jsonb;actual_row jsonb;changed integer;before_rows jsonb;expected_rows jsonb;
 patches jsonb:=$catalog_data$[{"id":"6cc541e2-b94d-4559-953c-652f0a2e20a4","name":"Primo soccorso ninja","before":{"description":"Bendaggi, stabilizzazione e trasporto consentono di assistere un ferito senza aggravare le sue lesioni, in attesa delle cure mediche."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/7/danno_effetto","kind":"editoriale_derivata"},{"id":"0cc20dad-a3c9-407b-908d-1ed95546a883","name":"Anatomia e vie del chakra","before":{"description":"Studio dei tenketsu, dei meridiani e dei punti vitali, alla base della diagnosi e degli interventi chirurgici ninja."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/8/danno_effetto","kind":"editoriale_derivata"},{"id":"5373c710-7879-494a-adaa-d0b3e446b523","name":"Diagnosi","before":{"description":"Il medico osserva il flusso di chakra del paziente per riconoscere la natura e la gravità delle sue lesioni."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/9/danno_effetto","kind":"editoriale_derivata"},{"id":"44628ea9-89fb-402c-bd35-86017bf0c177","name":"Coagulazione","before":{"description":"Il chakra viene concentrato sulle lesioni per arrestare il sanguinamento prima di procedere alle cure."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/10/danno_effetto","kind":"editoriale_derivata"},{"id":"f51dfd89-67c0-49ae-b463-53564adedce6","name":"Scalpello di Chakra","before":{"description":"Una lama di chakra permette di intervenire sui tessuti senza aprire la pelle; rivolta contro un avversario può recidere muscoli e tendini."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/11/danno_effetto","kind":"editoriale_derivata"},{"id":"578170b7-c58d-48cf-9628-9b643b2f71ea","name":"Intervento sui punti vitali","before":{"description":"Un intervento mirato ripara organi e nervi danneggiati. Richiede tempo e concentrazione, perché un errore può aggravare la lesione."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/12/danno_effetto","kind":"editoriale_derivata"},{"id":"f44a044d-e011-488f-a447-eb4c5fe6f246","name":"Sigillo serbatoio","before":{"description":"Un sigillo raccoglie in anticipo chakra curativo da utilizzare durante un intervento prolungato."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/13/danno_effetto","kind":"editoriale_derivata"},{"id":"34dfc010-a88c-45dd-8a8c-884072cab6a3","name":"Rianimazione d'équipe","before":{"description":"Più medici uniscono il proprio lavoro in un lungo intervento per soccorrere un paziente morente."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/14/danno_effetto","kind":"editoriale_derivata"},{"id":"d8ab210d-b5f5-405f-bac9-aaa60b43c835","name":"Analisi tossicologica","before":{"description":"L’esame della sostanza permette di riconoscere il veleno e individuare l’antidoto adatto."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/15/danno_effetto","kind":"editoriale_derivata"},{"id":"1da74dcc-2f0b-470d-a53a-4bbbbae985ab","name":"Siero universale d'emergenza","before":{"description":"Un antidoto generico del kit medico rallenta l’avvelenamento e concede tempo per cercare una cura specifica."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/16/danno_effetto","kind":"editoriale_derivata"},{"id":"60eceb0b-d5ef-4e6b-991e-d312910efa78","name":"Preparazione di antidoti","before":{"description":"Erbe, componenti e conoscenze mediche vengono combinati per preparare un antidoto specifico al veleno esaminato."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/17/danno_effetto","kind":"editoriale_derivata"},{"id":"8f7d57d3-fca6-4ae2-ae18-b3afbf5fcebd","name":"Estrazione di veleno","before":{"description":"Lo Scalpello di Chakra e il Palmo Curativo vengono combinati per estrarre il veleno dai tessuti del paziente."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/18/danno_effetto","kind":"editoriale_derivata"},{"id":"2f6f4895-80a2-4e66-b8f3-2a9016142c1f","name":"Nebbia Velenosa","before":{"description":"Il medico libera una nube tossica che ferisce e avvelena gli avversari, restando immune al proprio veleno."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/19/danno_effetto","kind":"editoriale_derivata"},{"id":"9a11a36b-1c7f-4ec4-8ccd-88054dee5696","name":"Recupero Stamina","before":{"description":"Il medico aiuta un alleato a recuperare dalle fatiche di uno scontro prolungato, intervenendo sulle energie fisiche."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/20/danno_effetto","kind":"editoriale_derivata"},{"id":"79985f2e-98f3-441c-a74e-a7b69696fbcf","name":"Sigillo anti-dolore","before":{"description":"Un sigillo attenua temporaneamente il dolore, permettendo al ferito di muoversi o collaborare alle cure."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/21/danno_effetto","kind":"editoriale_derivata"},{"id":"e0ea0961-8613-4f70-b990-b928b0617f03","name":"Cura accelerata","before":{"description":"Una variante del Palmo Curativo destinata al triage dei feriti gravi, che richiede un intenso impiego di chakra e attenzione."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/22/danno_effetto","kind":"editoriale_derivata"},{"id":"7608a7b2-16f4-415f-b6ee-b261c74c9647","name":"Aumento del sangue","before":{"description":"Il chakra stimola la produzione di sangue nel paziente dopo perdite importanti o traumi estesi."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/23/danno_effetto","kind":"editoriale_derivata"},{"id":"7d4e57c0-34d7-48a1-88de-52d0dab6ed0d","name":"Sigillo di Accumulo","before":{"description":"Un sigillo raccoglie chakra nel tempo, preparando l’impiego delle arti mediche più impegnative."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/24/danno_effetto","kind":"editoriale_derivata"},{"id":"260d6e01-d7a9-4f0c-8099-