":{"description":"Codici e gesti condivisi consentono agli ANBU di comunicare posizioni, minacce e ordini in silenzio."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/31/danno_effetto","kind":"editoriale_derivata"},{"id":"b5e74901-d286-4bf7-9d97-5b6cb04320d0","name":"Passo felpato","before":{"description":"Il movimento viene reso più discreto, attenuando rumori e tracce per sottrarsi all’attenzione degli osservatori."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/32/danno_effetto","kind":"editoriale_derivata"},{"id":"17574280-c1f2-4d44-ad2f-223b639a1c60","name":"Kage Shuriken","before":{"description":"Un secondo proiettile segue il primo nel suo cono d’ombra, nascondendosi alla vista del bersaglio."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/33/danno_effetto","kind":"editoriale_derivata"},{"id":"6f7fbb86-3d25-4c78-ad67-ff582b8d3ca8","name":"Shunshin d'assalto","before":{"description":"Uno spostamento fulmineo chiude la distanza e accompagna il colpo contro un avversario già in difficoltà."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/34/danno_effetto","kind":"editoriale_derivata"},{"id":"f924c74a-6956-4d74-9287-e2b6a243bf5a","name":"Prese d'Ombra Striscianti","before":{"description":"Braccia d’ombra si allungano verso il bersaglio e lo afferrano per ostacolarne i movimenti."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/35/danno_effetto","kind":"editoriale_derivata"},{"id":"491303f3-7a83-4a0f-bfb1-a39e6496568d","name":"Colpo al punto vitale","before":{"description":"Un affondo di precisione cerca un punto vitale dell’avversario per superarne in parte la resistenza fisica."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/36/danno_effetto","kind":"editoriale_derivata"},{"id":"1f1891db-87f7-40d6-882f-30c58f5e2648","name":"Veleno da lama","before":{"description":"Una tossina viene applicata all’arma perché il colpo possa trasmettere il veleno al bersaglio."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/37/danno_effetto","kind":"editoriale_derivata"},{"id":"e87fe791-66c8-4433-8d4f-0130148b582e","name":"Fendente silente","before":{"description":"Il chakra soffoca il suono dell’attacco per colpire senza diffondere l’allarme."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/38/danno_effetto","kind":"editoriale_derivata"},{"id":"d831089c-b526-40cd-bfbe-622601e29e56","name":"Sigillo tracciante","before":{"description":"Un sigillo lasciato al contatto consente di seguire la direzione del bersaglio dopo l’incontro."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/39/danno_effetto","kind":"editoriale_derivata"},{"id":"e504a675-cada-429f-9f32-9be3bb7d7fd0","name":"Doppia lama","before":{"description":"L’uso coordinato di due armi permette di accompagnare un attacco con un secondo colpo ravvicinato."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/40/danno_effetto","kind":"editoriale_derivata"},{"id":"e79109b1-bf77-4022-bd85-7fce7f837077","name":"Marchio della Morte","before":{"description":"Un sigillo assegnato dalla Regia identifica un bersaglio della missione e ne rende percepibile la direzione all’incaricato."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/41/danno_effetto","kind":"editoriale_derivata"},{"id":"6f5de78f-f3e6-40fe-b31f-8d02d68c3271","name":"Occhio del falco","before":{"description":"Un addestramento visivo dedicato alla lettura labiale e al riconoscimento di segni e sigilli a distanza."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/42/danno_effetto","kind":"editoriale_derivata"},{"id":"f917f9b3-79f0-4679-afb8-f2fbaf5511a5","name":"Passo del fantasma","before":{"description":"Il ninja controlla l’appoggio dei piedi per cancellare rumori e vibrazioni durante il movimento."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/43/danno_effetto","kind":"editoriale_derivata"},{"id":"aaf4a9b2-8523-4f9d-beae-74dff19507a4","name":"Traccia di sangue","before":{"description":"L’addestramento permette di inseguire una persona a partire da tracce minime lasciate sul percorso."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/44/danno_effetto","kind":"editoriale_derivata"},{"id":"6a7e1ff7-2af7-4ffc-a089-e19fd6e80ea4","name":"Tracciamento olfattivo","before":{"description":"Il chakra affina l’olfatto per seguire una traccia recente."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/45/danno_effetto","kind":"editoriale_derivata"},{"id":"d0a1d41b-7e6c-467a-8d75-745df4fe824e","name":"Meisai Gakure","before":{"description":"Una tecnica di occultamento avanzata che sfrutta le zone d’ombra per celare quasi completamente la presenza."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/46/danno_effetto","kind":"editoriale_derivata"},{"id":"9b2d216a-a5e5-42db-9623-b65536d5fa39","name":"Clone-esca ANBU","before":{"description":"Un clone viene lasciato a osservare o a presidiare una seconda via, senza prendere parte al combattimento."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/47/danno_effetto","kind":"editoriale_derivata"},{"id":"eef2d026-76e0-45c8-a2e8-9030b9b40c57","name":"Sigillo del segugio","before":{"description":"Un sigillo su un oggetto toccato dal bersaglio conserva un riferimento alla sua direzione."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/48/danno_effetto","kind":"editoriale_derivata"},{"id":"67a1e24e-f1a1-424c-952e-9b6f803369a3","name":"Ombra condivisa","before":{"description":"Un clone immobile prosegue l’osservazione mentre il ninja riposa, sostenendo i pedinamenti prolungati."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/49/danno_effetto","kind":"editoriale_derivata"},{"id":"a0233b42-d1a0-4125-afaa-92313af24bae","name":"Sensibilità ai tenketsu","before":{"description":"La percezione del flusso di chakra altrui aiuta a leggere l’interlocutore e distinguere una persona da un clone."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/50/danno_effetto","kind":"editoriale_derivata"},{"id":"307764cb-3564-4e8e-afd0-a53ed9af918d","name":"Lettura della firma","before":{"description":"Al contatto, il ninja esamina la firma di chakra altrui per raccogliere informazioni sul suo stato e sulla sua natura."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/51/danno_effetto","kind":"editoriale_derivata"},{"id":"4889733c-459f-4e36-b938-ad38adc88f55","name":"Allarme silenzioso","before":{"description":"Un sigillo segnala una minaccia agli ANBU alleati senza emettere suoni udibili."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/52/danno_effetto","kind":"editoriale_derivata"},{"id":"80e23120-1e20-441b-877f-8b81f155195d","name":"Kagura Shingan","before":{"description":"Una percezione estesa del chakra rivela presenze e movimenti prima che diventino visibili."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/53/danno_effetto","kind":"editoriale_derivata"},{"id":"030eebfc-15ab-466f-ba11-e13629479efd","name":"Barriera-sensore","before":{"description":"Una barriera di sigilli delimita un perimetro e segnala le presenze che lo attraversano."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/54/danno_effetto","kind":"editoriale_derivata"},{"id":"c60f62c3-be5b-41b6-88a1-7823ebc3099e","name":"Mappa mentale del campo","before":{"description":"Le presenze percepite vengono organizzate in una rappresentazione mentale e comunicate alla squadra."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/55/danno_effetto","kind":"editoriale_derivata"},{"id":"1a30e45a-5da9-4077-94eb-ae57d40b5f58","name":"Riconoscimento della firma","before":{"description":"L’analisi della firma di chakra permette di confrontare un’apparenza con la presenza che la sostiene."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/56/danno_effetto","kind":"editoriale_derivata"},{"id":"38ee3215-251e-4a10-b627-35fe21fc17ad","name":"Sigillo di trasmissione","before":{"description":"Brevi impulsi di chakra consentono una comunicazione silenziosa con un ANBU che porta il marchio adatto."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/57/danno_effetto","kind":"editoriale_derivata"},{"id":"2305a98a-ca53-4f40-a76f-d2c3a1735e37","name":"Vista lontana","before":{"description":"L’attenzione si estende a grande distanza, richiedendo immobilità e concentrazione costanti."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/58/danno_effetto","kind":"editoriale_derivata"},{"id":"36382719-7cc1-43bf-b2e9-6af711e094ad","name":"Volto vuoto","before":{"description":"Una disciplina del controllo corporeo che modifica voce, postura e andatura, celando le microespressioni."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/59/danno_effetto","kind":"editoriale_derivata"},{"id":"c5ae2673-431e-4ca0-ac29-fac83120f981","name":"Trasformazione parziale","before":{"description":"Una trasformazione mirata modifica singoli tratti fisici per sostenere un’identità di copertura."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/60/danno_effetto","kind":"editoriale_derivata"},{"id":"4f5cc678-8b58-48e0-a470-32e1685c7360","name":"Clone-copertura","before":{"description":"Un doppio visibile e immobile conserva l’apparenza della presenza del ninja mentre questi agisce altrove."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/61/danno_effetto","kind":"editoriale_derivata"},{"id":"67581395-c345-48ed-9409-107a000102c1","name":"Falsificazione dei sigilli","before":{"description":"Lo studio di grafie e controlli locali permette di contraffare documenti, marchi e sigilli credibili."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/62/danno_effetto","kind":"editoriale_derivata"},{"id":"ebebe1b8-5334-4eaf-ac74-6d546e92b068","name":"Passepartout del chakra","before":{"description":"Il chakra viene concentrato su serrature semplici e barriere minori per aprirle senza distruggerle."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/63/danno_effetto","kind":"editoriale_derivata"},{"id":"7f79ffdc-fd3a-44c1-b7c4-ee4ea671b99d","name":"Camminata sul soffitto","before":{"description":"Il controllo dell’aderenza viene applicato al movimento a testa in giù, sopra le normali vie di sorveglianza."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/64/danno_effetto","kind":"editoriale_derivata"},{"id":"a590c602-fe92-431c-8de7-2cb48f7c3eb6","name":"Henge avanzato","before":{"description":"Una trasformazione prolungata sostiene un’identità di copertura e resiste a osservazioni sommarie."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/65/danno_effetto","kind":"editoriale_derivata"},{"id":"0a1accd6-8c02-4602-af2d-1dfd41a49351","name":"Sigillo dell'identità vuota","before":{"description":"Un sigillo oscura la firma di chakra per rendere più difficile l’individuazione sensoriale."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/66/danno_effetto","kind":"editoriale_derivata"},{"id":"94494854-f89a-4a07-96ac-f7f51680d0ef","name":"Travestimento nel sonno","before":{"description":"L’addestramento mantiene il travestimento anche durante il sonno o la perdita di coscienza."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/67/danno_effetto","kind":"editoriale_derivata"},{"id":"51e46507-24e3-43d1-8f39-310fae6c2908","name":"Sigillo di Contenimento","before":{"description":"Un sigillo viene impiegato per sopprimere o contenere un marchio maledetto ostile."},"after":{"description":null},"source":"catalog.baseline.json#/catalog/68/danno_effetto","kind":"editoriale_derivata"},{"id":"127f3854-4183-4354-a654-f59320d8807e","name":"Aghi Velenosi","before":{"danno_base":10,"potenza":20,"portata":"15 metri","bersaglio":"Un bersaglio nemico","tipo_azione":"Azione principale","durata":"Impatto istantaneo; Veleno minore nei due turni personali successivi del bersaglio","danno_effetto":"Danno base 10, Potenza base 20. Un colpo pieno su un bersaglio ancora in piedi applica Veleno minore: fino a 5 PV per ciascuno dei due turni personali successivi. Un nuovo contatto non rinnova un veleno già attivo. Consuma 2 unità della Riserva del Veleno."},"after":{"danno_base":15,"potenza":null,"portata":null,"bersaglio":null,"tipo_azione":null,"durata":null,"danno_effetto":null},"source":"REGOLE.md pubblicato §5.6, needle_ability/needle_frozen_profile/body_contact/bind_staff_profile vivi","kind":"riallineamento_al_contratto_pubblico"},{"id":"c8d32b00-3917-41a6-8906-388e7b9efcc7","name":"Corpo Tossico","before":{"danno_base":0,"portata":"Contatto a mani nude, senza protezione interposta","bersaglio":"Sé stesso; trasmissione per contatto corporeo con un avversario","tipo_azione":"Attivazione nel proprio turno, senza consumare l’azione principale","durata":"Massimo tre turni personali, compreso quello di attivazione","danno_effetto":"Nessun danno diretto. Il contatto pieno a mani nude, senza protezione interposta, può applicare Veleno minore sia colpendo sia venendo colpiti; vale anche se il portatore viene mandato KO. Impegna 5 unità della Riserva del Veleno; una nuova applicazione consuma una unità per round. Il veleno sottrae fino a 5 PV per ciascuno dei due turni personali successivi e un nuovo contatto non ne rinnova la scadenza. Alla fine si liberano le unità ancora impegnate."},"after":{"danno_base":15,"portata":null,"bersaglio":null,"tipo_azione":null,"durata":null,"danno_effetto":null},"source":"REGOLE.md pubblicato §5.6, needle_ability/needle_frozen_profile/body_contact/bind_staff_profile vivi","kind":"riallineamento_al_contratto_pubblico"}]$catalog_data$::jsonb;
BEGIN
 IF (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(t) ORDER BY id)) FROM public.clan_techniques t)
  IS DISTINCT FROM '3137b892d25c4d4b20177dbee5529829d7cde7a31db3bc0d3f5ea220867899b0' THEN RAISE EXCEPTION 'CATALOG_BASELINE_DRIFT';END IF;
 IF (SELECT public.combat_v2_sha256(jsonb_agg(to_jsonb(j) ORDER BY id)) FROM public.jutsu j)
  IS DISTINCT FROM 'ac80f965af32d580f44ba8c0d2dfcd9dad44d3a6f56b903462c76137fe172e25' THEN RAISE EXCEPTION 'CATALOG_JUTSU_DRIFT';END IF;
 IF md5(pg_get_functiondef('clan_hoki_private.needle_ability(uuid,boolean)'::regprocedure)) IS DISTINCT FROM '7427153cedf2f97fdd247f6726f66fa6' OR md5(pg_get_functiondef('clan_hoki_private.body_contact(uuid,uuid)'::regprocedure)) IS DISTINCT FROM 'd276255e1ef09155a4eddc7573f55f7b' OR md5(pg_get_functiondef('clan_hoki_private.bind_staff_profile(uuid,uuid)'::regprocedure)) IS DISTINCT FROM '88b02e3e582f4cd76568a0dec54b460b' THEN RAISE EXCEPTION 'CATALOG_HOKI_RUNTIME_DRIFT';END IF;
 IF (SELECT jsonb_agg(to_jsonb(g) ORDER BY technique_id) FROM clan_hoki_private.release_gate g)
  IS DISTINCT FROM $catalog_gate$[{"technique_id":"127f3854-4183-4354-a654-f59320d8807e","staff_enabled":true,"public_enabled":true},{"technique_id":"c8d32b00-3917-41a6-8906-388e7b9efcc7","staff_enabled":true,"public_enabled":true}]$catalog_gate$::jsonb THEN RAISE EXCEPTION 'CATALOG_HOKI_GATE_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE state='in_corso') THEN RAISE EXCEPTION 'CATALOG_COMBAT_OPEN';END IF;
 IF (SELECT count(*) FROM public.clan_techniques)<>362 OR (SELECT count(*) FROM public.clan_techniques WHERE is_active)<>337 THEN RAISE EXCEPTION 'CATALOG_INVENTORY_DRIFT';END IF;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO before_rows FROM public.clan_techniques t;
 FOR patch IN SELECT value FROM jsonb_array_elements(patches) ORDER BY value->>'id' LOOP
  IF jsonb_typeof(patch->'after')<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(patch->'after') k WHERE k NOT IN('description','danno_base','potenza','portata','bersaglio','tipo_azione','durata','danno_effetto')) THEN RAISE EXCEPTION 'CATALOG_PATCH_KEYS';END IF;
  SELECT to_jsonb(t) INTO STRICT current_row FROM public.clan_techniques t WHERE t.id=(patch->>'id')::uuid AND t.is_active FOR UPDATE;
  IF (SELECT jsonb_object_agg(k,current_row->k) FROM jsonb_object_keys(patch->'before') k) IS DISTINCT FROM patch->'before' THEN RAISE EXCEPTION 'CATALOG_ROW_DRIFT:%',patch->>'id';END IF;
  expected_row:=current_row||(patch->'after');
  UPDATE public.clan_techniques SET description=expected_row->>'description',danno_base=(expected_row->>'danno_base')::integer,
    potenza=(expected_row->>'potenza')::integer,portata=expected_row->>'portata',bersaglio=expected_row->>'bersaglio',
    tipo_azione=expected_row->>'tipo_azione',durata=expected_row->>'durata',danno_effetto=expected_row->>'danno_effetto'
  WHERE id=(patch->>'id')::uuid AND is_active;
  GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'CATALOG_UPDATE_COUNT';END IF;
  SELECT to_jsonb(t) INTO STRICT actual_row FROM public.clan_techniques t WHERE t.id=(patch->>'id')::uuid;
  IF actual_row IS DISTINCT FROM expected_row THEN RAISE EXCEPTION 'CATALOG_UNEXPECTED_DELTA:%',patch->>'id';END IF;
 END LOOP;
 SELECT jsonb_agg(CASE WHEN p.value IS NULL THEN r.value ELSE r.value||(p.value->'after') END ORDER BY r.value->>'id') INTO expected_rows
 FROM jsonb_array_elements(before_rows) r LEFT JOIN LATERAL(SELECT value FROM jsonb_array_elements(patches) WHERE value->>'id'=r.value->>'id') p ON true;
 IF (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM public.clan_techniques t) IS DISTINCT FROM expected_rows
  OR public.combat_v2_sha256(expected_rows) IS DISTINCT FROM 'bcc5b6e27a7380801d17db1878b579d24ccdbdca03508630019e9df8dfc7e41d' THEN RAISE EXCEPTION 'CATALOG_TABLE_CUSTODY';END IF;
END $catalog_patch$;
COMMIT;
